{ kind: 'branch-sync', branch: 'lane/mechanical-dispatcher', state: 'awaiting-fast-forward',   // or 'agent-failed'
  behind: 58, signature: '3e72ad5516ad', since: '2026-09-14T23:04:44Z',
  line: 'lane/mechanical-dispatcher: staged merge ready on lane/mechanical-dispatcher-catchup, fast-forward it' }

// we:scripts/lib/review-escalation.mjs — pure; the probe sits beside computeNetDiffText in merge-ai-prs.mjs
export function mergeOnlyCarry({ reviewedSha, reviewedPaths, chain, readFailed }) {
  // chain: head → reviewedSha. Each: { sha, parents, prParent, mainParentIsMainAncestor,
  //                                    replayClean, replayTree, tree, mainSidePaths }
  if (readFailed || !reviewedSha || !chain?.length) return { carries: false, reason: 'unproven' };
  for (const [i, c] of chain.entries()) {
    // linkage: the pure function re-checks the walk, it does not trust the probe to have built one path
    if (i + 1 < chain.length && c.prParent !== chain[i + 1].sha)
      return { carries: false, reason: `${c.sha}: chain is disconnected` };
    if (c.parents.length !== 2 || !c.prParent || !c.mainParentIsMainAncestor)
      return { carries: false, reason: `${c.sha} is not a merge of main into the reviewed branch` };
    if (!c.replayClean) return { carries: false, reason: `${c.sha}: the merge had conflicts` };
    if (c.replayTree !== c.tree) return { carries: false, reason: `${c.sha}: tree differs from git's own merge` };
    if (c.mainSidePaths.some((p) => reviewedPaths.has(p)))              // Fork 2
      return { carries: false, reason: `${c.sha}: main changed this PR's files` };
  }
  if (chain.at(-1).prParent !== reviewedSha) return { carries: false, reason: 'path does not reach reviewed-sha' };
  return { carries: true, from: reviewedSha, to: chain[0].sha, tree: chain[0].tree };
}
// probe: git merge-tree --write-tree <p1> <p2>        exit 0 = clean; first line = tree
//        git rev-parse <sha>^{tree}
//        git diff --name-only <prParent> <sha>         = mainSidePaths (no merge-base needed)
//        every replay runs hermetic: -c rerere.enabled=false -c attr.tree=<empty tree>, no drivers, no -X
// apply: restamp --expect-head=<chain[0].sha>        refuses if the live head moved after the proof

// Fork 2 (a): one more arm in classifyPr's skip chain (we:scripts/merge-ai-prs.mjs:616-629), ahead of the
// required-check arm, so the named reason wins over "required check "test" is not green".
// `baseRefName` is already in the drain's `gh pr list --json` field list (we:scripts/merge-ai-prs.mjs:3547).
// `defaultBranch` is the repo's default branch, passed in by the caller (not a literal 'main').
else if (pr?.baseRefName && pr.baseRefName !== defaultBranch) { decision = 'skip'; reason = `base is not ${defaultBranch} (${pr.baseRefName}) — POC-branch PRs are not drained (#3805)`; }
else if (!testGreen) { decision = 'skip'; reason = `required check "${requiredCheck}" is not green`; }
